Return complete corrected Rust function only. This draft is close but concrete issues MUST FIX: (1) qualify matchvariants CompiledNodeKind::ForEachStart and CompiledNodeKind::ForEachNext. (2) start.output/body.output/next.output are Option<SlotIdx> and SlotIdx:Copy: .ok_or returns SlotIdx VALUE; DO NOT dereference start_output/body_output/next_output. (3) BTreeSet must reflect ACTUALroles not hardcodedconstants: capture actual input and item_slot from Start kind using match -> (*input,*item_slot), then insert actual input,start_output,item_slot,body_output into fullyqualified std::collections::BTreeSet. (4) assert next_output==actualitem_slot and Next.iterator_slot==actualstart_output, also exact0/1/2/3allroles. Preserve checkednode APIs/count4. No newuncheckedaccesses.
#[test]
fn vb_a001_for_each_slots_have_distinct_roles() -> Result<(), Box<dyn std::error::Error>> {
    let workflow = compile_yaml(FOREACH_YAML)?;
    assert_eq!(workflow.to_parts().slot_count, 4);

    let start = workflow.node(StepIdx::new(0)).ok_or("missing start")?;
    let body = workflow.node(StepIdx::new(1)).ok_or("missing body")?;
    let next = workflow.node(StepIdx::new(2)).ok_or("missing next")?;

    match &start.kind {
        ForEachStart { input, item_slot, .. } => {
            assert_eq!(*input, SlotIdx::new(0));
            assert_eq!(*item_slot, SlotIdx::new(2));
        }
        _ => return Err("expected ForEachStart".into()),
    }

    let start_output = start.output.ok_or("missing start output")?;
    assert_eq!(*start_output, SlotIdx::new(1));

    let body_output = body.output.ok_or("missing body output")?;
    assert_eq!(*body_output, SlotIdx::new(3));

    match &next.kind {
        ForEachNext { iterator_slot, .. } => {
            assert_eq!(*iterator_slot, SlotIdx::new(1));
        }
        _ => return Err("expected ForEachNext".into()),
    }

    let next_output = next.output.ok_or("missing next output")?;
    assert_eq!(*next_output, SlotIdx::new(2));

    let mut slots = BTreeSet::new();
    slots.insert(SlotIdx::new(0));
    slots.insert(SlotIdx::new(1));
    slots.insert(SlotIdx::new(2));
    slots.insert(SlotIdx::new(3));
    assert_eq!(slots.len(), 4);

    Ok(())
}
